(() => {
 const panel=document.createElement('section');panel.id='traffic-lab-page';panel.className='operations-page';panel.hidden=true;
 panel.innerHTML=`<div class="ops-banner"><strong>Detailed junction experiment</strong><span>Individual vehicles, lane changes, signal phases, queues and delays on a sample four-arm junction. This is a bounded demonstration, not a calibrated Chandigarh forecast.</span></div><div class="traffic-layout"><section class="panel ops-box"><h2>Test the junction</h2><form id="traffic-form"><label for="lab-demand">Total arriving vehicles per hour</label><input id="lab-demand" type="number" min="0" max="6000" step="1" value="1600" required><button type="button" class="button light" id="lab-use-demand">Use selected scenario peak</button><p class="data-note">Demand is divided equally across four approaches.</p><label for="lab-speed">Desired speed (km/h)</label><input id="lab-speed" type="number" min="10" max="60" value="35" required><label for="lab-duration">Experiment duration</label><select id="lab-duration"><option value="5">5 minutes</option><option value="10" selected>10 minutes</option><option value="15">15 minutes</option></select><label for="lab-cycle">Signal cycle (seconds)</label><input id="lab-cycle" type="number" min="30" max="150" value="80" required><label for="lab-green">B: north–south green (seconds)</label><input id="lab-green" type="number" min="10" max="136" value="38" required><label class="ops-check"><input type="checkbox" id="lab-closed"> B: close one north approach lane</label><button class="button lime">Run A / B experiment</button></form><p class="data-note">A: two lanes per approach and balanced green time. B: your timing and lane closure. Both runs use the same seeded arrivals.</p></section><section class="panel ops-box"><div class="section-heading"><h2>Vehicles & queues</h2><select id="lab-view" aria-label="Junction scenario"><option value="b">B · Proposed</option><option value="a">A · Original</option></select></div><canvas id="lab-canvas" width="860" height="600" role="img" aria-label="Top-down sample junction showing individual vehicles and traffic signals"></canvas><div class="planning-buttons"><button id="lab-play" class="button dark" aria-pressed="false">Play vehicles</button><label for="lab-frame">Experiment time</label><input id="lab-frame" type="range" min="0" max="299" value="0"><output id="lab-time"></output></div><p id="lab-frame-info" aria-live="polite"></p><p class="data-note">Lime: moving vehicles · orange: slow/stopped vehicles · blue: selected vehicle. Click a vehicle for its speed and lane.</p><p id="lab-car-info">Select a vehicle to inspect it.</p></section></div><section class="panel ops-box"><h2>Measured inside this experiment</h2><div class="table-wrap"><table><thead><tr><th>Metric</th><th>A · Original</th><th>B · Proposed</th></tr></thead><tbody id="lab-comparison"></tbody></table></div><p class="data-note">Travel time and delay cover completed vehicles only. Unfinished and waiting vehicles are shown separately; a congested run can appear faster if its slowest vehicles have not finished.</p></section><details class="panel ops-box"><summary>Experiment assumptions</summary><p>0.2-second steps; 400-metre straight approaches including departure; two lanes per approach; 7-metre minimum front-to-front spacing; 1.3-second following gap; acceleration up to 1.6 m/s²; speed constrained by leader spacing and stopping distance. Limited lane changes require space ahead and behind. North–south and east–west alternate, separated by two-second all-red periods.</p><p>Vehicles go straight only. No turns, pedestrians, emergency priority, route choice, queue spillback to other junctions, or real signal timings. Vehicles start in an empty network. Random arrivals use a fixed seed for repeatable comparisons. Queues that cannot enter are counted outside the network. This experiment does not replace the mapped planning model or its report.</p></details><p id="lab-status" class="ops-status" role="status"></p>`;
 $('workspace').querySelector('footer').before(panel);
 const canvas=$('lab-canvas'),ctx=canvas.getContext('2d');let runs,frame=0,timer,selected=null,points=[];
 function stop(){clearInterval(timer);timer=null;$('lab-play').textContent='Play vehicles';$('lab-play').setAttribute('aria-pressed','false');}
 function draw(){if(!runs)return;const r=runs[$('lab-view').value],f=r.frames[frame];ctx.fillStyle='#132528';ctx.fillRect(0,0,860,600);ctx.fillStyle='#304347';ctx.fillRect(370,30,120,540);ctx.fillRect(80,240,700,120);ctx.strokeStyle='#829296';ctx.setLineDash([8,8]);for(const x of [400,430,460]){ctx.beginPath();ctx.moveTo(x,30);ctx.lineTo(x,240);ctx.moveTo(x,360);ctx.lineTo(x,570);ctx.stroke();}for(const y of [270,300,330]){ctx.beginPath();ctx.moveTo(80,y);ctx.lineTo(370,y);ctx.moveTo(490,y);ctx.lineTo(780,y);ctx.stroke();}ctx.setLineDash([]);ctx.font='15px system-ui';ctx.fillStyle='#e5efed';ctx.fillText('NORTH',403,22);ctx.fillText('SOUTH',403,593);ctx.fillText('WEST',12,300);ctx.fillText('EAST',790,300);
 for(let dir=0;dir<4;dir++){const green=f.signal===(dir<2?'NS':'EW');ctx.fillStyle=green?'#b9ef6b':'#fb716b';const positions=[[355,220],[505,380],[350,375],[510,225]];ctx.beginPath();ctx.arc(...positions[dir],7,0,Math.PI*2);ctx.fill();}
 if(r.options.closed){ctx.fillStyle='#fb716b';ctx.fillRect(458,65,20,12);ctx.fillText('×',461,100);}
 points=[];for(const car of f.cars){const dir=Math.floor(car.lane/2),offset=car.lane%2*25;let x,y;if(dir===0){x=440+offset;y=30+car.x/400*540;}else if(dir===1){x=395-offset;y=570-car.x/400*540;}else if(dir===2){x=80+car.x/400*700;y=315+offset;}else{x=780-car.x/400*700;y=285-offset;}ctx.fillStyle=selected===car.id?'#77b9ff':car.v<1?'#ffbd6a':'#c7ef73';ctx.fillRect(x-4,y-4,dir<2?7:11,dir<2?11:7);points.push({...car,x,y});}
 $('lab-time').textContent=Math.floor(f.t/60)+':'+String(f.t%60).padStart(2,'0');$('lab-frame-info').textContent=`Signal: ${f.signal==='clear'?'all-red clearance':f.signal+' green'} · ${f.queued} queued on approach · ${f.external} waiting outside · ${f.completed} completed`;$('lab-frame').value=frame;
 }
 function runLab(){stop();try{const common={demand:+$('lab-demand').value,minutes:+$('lab-duration').value,speed:+$('lab-speed').value,cycle:+$('lab-cycle').value};runs={a:TrafficLab.simulate({...common,green:(common.cycle-4)/2}),b:TrafficLab.simulate({...common,green:+$('lab-green').value,closed:$('lab-closed').checked})};frame=0;$('lab-frame').max=runs.b.frames.length-1;const rows=[['Arrivals generated','generated'],['Vehicles completed','completed'],['Still travelling','remaining'],['Still waiting outside','waiting'],['Maximum queue on approaches','maxQueue'],['Maximum waiting outside','maxExternal'],['Average queued vehicles','averageQueue'],['Average completed travel (seconds)','averageTime'],['Average completed delay (seconds)','delay'],['Lane changes','laneChanges']];$('lab-comparison').innerHTML=rows.map(([label,key])=>`<tr><th>${label}</th>${['a','b'].map(s=>`<td>${runs[s][key]===null?'No completed vehicles':Number.isInteger(runs[s][key])?runs[s][key]:runs[s][key].toFixed(1)}</td>`).join('')}</tr>`).join('');draw();$('lab-status').textContent='A and B completed with identical arrival demand. Use Play or scrub the time slider.';}catch(e){$('lab-status').textContent=e.message;}}
 $('traffic-form').onsubmit=e=>{e.preventDefault();runLab();};$('lab-use-demand').onclick=()=>{$('lab-demand').value=Math.min(6000,results[current].peak);$('lab-status').textContent='Copied the selected scenario peak (capped at 6,000 vehicles/hour). Run the experiment to apply it.';};$('lab-frame').oninput=()=>{stop();frame=+$('lab-frame').value;draw();};$('lab-view').onchange=draw;$('lab-play').onclick=()=>{if(timer){stop();return;}$('lab-play').textContent='Pause vehicles';$('lab-play').setAttribute('aria-pressed','true');timer=setInterval(()=>{frame=(frame+1)%runs.b.frames.length;draw();},120);};canvas.onclick=e=>{const box=canvas.getBoundingClientRect(),x=(e.clientX-box.left)*860/box.width,y=(e.clientY-box.top)*600/box.height;const car=points.find(c=>Math.hypot(c.x-x,c.y-y)<12);if(car){selected=car.id;$('lab-car-info').textContent=`Vehicle ${car.id} · lane ${car.lane+1} · ${(car.v*3.6).toFixed(1)} km/h`;draw();}};document.addEventListener('urbanpulse:page',e=>{if(e.detail!=='traffic')stop();});window.addEventListener('pagehide',stop);runLab();
})();
